from collections import deque


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007

    if n == 0:
        return 1

    banned = [word for word in banned if len(word) <= n]
    if not banned:
        return pow(len(alphabet), n, MOD)

    size = len(alphabet)
    char_index = {ch: i for i, ch in enumerate(alphabet)}

    transitions = [[-1] * size]
    failure = [0]
    forbidden = [False]

    for word in banned:
        state = 0
        for ch in word:
            c = char_index[ch]
            if transitions[state][c] == -1:
                transitions[state][c] = len(transitions)
                transitions.append([-1] * size)
                failure.append(0)
                forbidden.append(False)
            state = transitions[state][c]
        forbidden[state] = True

    queue = deque()
    for c in range(size):
        child = transitions[0][c]
        if child == -1:
            transitions[0][c] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        forbidden[state] |= forbidden[failure[state]]

        for c in range(size):
            child = transitions[state][c]
            if child == -1:
                transitions[state][c] = transitions[failure[state]][c]
            else:
                failure[child] = transitions[failure[state]][c]
                queue.append(child)

    valid_states = [
        state for state in range(len(transitions)) if not forbidden[state]
    ]
    index = {state: i for i, state in enumerate(valid_states)}
    dimension = len(valid_states)

    matrix = [[0] * dimension for _ in range(dimension)]
    for state in valid_states:
        row = matrix[index[state]]
        for target in transitions[state]:
            if not forbidden[target]:
                row[index[target]] += 1

    def multiply(a, b):
        result = [[0] * dimension for _ in range(dimension)]
        for i, a_row in enumerate(a):
            result_row = result[i]
            for k, value in enumerate(a_row):
                if value:
                    for j, other in enumerate(b[k]):
                        if other:
                            result_row[j] += value * other
            for j in range(dimension):
                result_row[j] %= MOD
        return result

    counts = [0] * dimension
    counts[index[0]] = 1

    while n:
        if n & 1:
            updated = [0] * dimension
            for i, count in enumerate(counts):
                if count:
                    for j, ways in enumerate(matrix[i]):
                        if ways:
                            updated[j] += count * ways
            counts = [value % MOD for value in updated]

        n >>= 1
        if n:
            matrix = multiply(matrix, matrix)

    return sum(counts) % MOD
